import type { Page } from "@playwright/test";
import { readdirSync, readFileSync } from "node:fs";
import { test, expect } from "./coverage";

// The public example pages — /examples/ and one /examples/<id>/ page per
// example — generated by examples/validation/run.mjs --report (which also
// checks, on every CI run, that their numbers still match the engine). These
// tests check that the pages are served, complete and indexable, and that
// every example's in-app reproduction holds: opening it in KoFEM and solving
// it shows exactly the read-out its page publishes.

// Every example has a page directory, written by run.mjs --report.
const IDS = readdirSync("examples", { withFileTypes: true })
  .filter((entry) => entry.isDirectory())
  .map((entry) => entry.name);

type Published = {
  engine: string;
  cases: { id: string; name: string }[];
  convergence: { id: string; series: { caseId: string }[] }[];
};

const published = (): Published =>
  JSON.parse(readFileSync("public/examples/results.json", "utf8")) as Published;

// The value the app's Result summary shows for `stat` (e.g. "Min Uy").
function summaryValue(page: Page, stat: string) {
  return page
    .getByText(stat, { exact: true })
    .locator("xpath=following-sibling::span[1]");
}

test("/examples/ lists every example, links its page and shows the results", async ({
  page,
}) => {
  const data = published();
  await page.goto("/examples/");

  await expect(
    page.getByRole("heading", { level: 1, name: "Examples" }),
  ).toBeVisible();
  await expect(page.locator('link[rel="canonical"]')).toHaveAttribute(
    "href",
    "https://kofem.org/examples/",
  );
  await expect(page.locator('meta[name="description"]')).toHaveAttribute(
    "content",
    /known result/,
  );
  await expect(page.getByTestId("disclaimer")).toContainText(
    "not certified for safety-critical design",
  );
  await expect(page.locator(".meta").first()).toContainText(
    `engine ${data.engine}`,
  );

  // One entry per example, each with its figure and a link to its page; every
  // benchmark also has a row in the results table.
  const entries = page.locator("li[data-entry]");
  await expect(entries).toHaveCount(IDS.length);
  const order = await entries.evaluateAll((els) =>
    els.map((e) => e.getAttribute("data-entry") ?? ""),
  );
  expect([...order].sort()).toEqual([...IDS].sort());
  for (const id of order) {
    const entry = page.locator(`li[data-entry="${id}"]`);
    await expect(entry.getByRole("heading", { level: 3 })).toBeVisible();
    await expect(entry.getByRole("link").last()).toHaveAttribute(
      "href",
      `/examples/${id}/`,
    );
    await expect(entry.locator("img")).toHaveAttribute(
      "src",
      `/examples/${id}.png`,
    );
  }
  for (const c of data.cases)
    await expect(
      page
        .locator("table.results")
        .getByRole("link", { name: c.name, exact: true }),
    ).toHaveAttribute("href", `/examples/${c.id}/`);

  // Listed for crawlers: the index and every example page.
  const sitemap = await (await page.request.get("/sitemap.xml")).text();
  expect(sitemap).toContain("<loc>https://kofem.org/examples/</loc>");
  for (const id of IDS)
    expect(sitemap).toContain(`<loc>https://kofem.org/examples/${id}/</loc>`);
});

test("every example has its own indexable page with figure, model and result", async ({
  page,
}) => {
  const data = published();
  for (const [i, id] of IDS.entries()) {
    const res = await page.goto(`/examples/${id}/`);
    expect(res?.status()).toBe(200);
    await expect(page.locator('link[rel="canonical"]')).toHaveAttribute(
      "href",
      `https://kofem.org/examples/${id}/`,
    );
    await expect(page.locator('meta[name="robots"]')).toHaveAttribute(
      "content",
      "index, follow",
    );
    await expect(page.locator('meta[property="og:image"]')).toHaveAttribute(
      "content",
      `https://kofem.org/examples/${id}.png`,
    );
    const description = await page
      .locator('meta[name="description"]')
      .getAttribute("content");
    expect(description?.length ?? 0).toBeGreaterThan(50);
    const jsonLd = await page
      .locator('script[type="application/ld+json"]')
      .textContent();
    expect(JSON.parse(jsonLd ?? "")).toMatchObject({
      "@context": "https://schema.org",
    });

    // The result figure loads, and the page opens its own model.
    const figure = page.locator("figure.result img");
    await expect(figure).toHaveAttribute("src", `/examples/${id}.png`);
    await expect
      .poll(() =>
        figure.evaluate((img) => (img as HTMLImageElement).naturalWidth),
      )
      .toBeGreaterThan(0);
    await expect(page.getByTestId("open-in-app")).toHaveAttribute(
      "href",
      `/app/?example=${id}`,
    );
    const vtu = await page.request.get(`/examples/${id}.vtu`);
    expect(vtu.ok()).toBe(true);

    for (const section of [
      "problem",
      "theory",
      "model",
      "results",
      "discussion",
      "reproduce",
      "references",
    ])
      await expect(page.locator(`h2#${section}`)).toBeVisible();
    await expect(page.locator("figure.diagram svg").first()).toBeVisible();
    await expect(page.locator("main math").first()).toBeVisible();
    if (i === 0) {
      // Equations are set in the self-hosted LaTeX math font, not a fallback.
      const mathFont = await page.evaluate(async () => {
        await document.fonts.ready;
        return [...document.fonts]
          .filter((f) => f.family.replace(/"/g, "") === "KoFEM Math")
          .map((f) => f.status);
      });
      expect(mathFont).toEqual(["loaded"]);
    }
    await expect(page.locator("ol.refs li").first()).toBeVisible();
    await expect(page.getByTestId("disclaimer")).toBeVisible();

    // A benchmark prints its line; its convergence study, where it has one.
    const isCase = data.cases.some((c) => c.id === id);
    if (isCase) {
      await expect(page.getByTestId("fe-value")).not.toBeEmpty();
      await expect(page.locator("pre").first()).toContainText(
        `run.mjs --case ${id}`,
      );
    }
    const studies = data.convergence.filter((s) =>
      s.series.some((x) => x.caseId === id),
    );
    await expect(page.locator("[data-study]")).toHaveCount(studies.length);
    for (const s of studies)
      await expect(
        page.locator(`[data-study="${s.id}"] figure.chart svg`),
      ).toBeVisible();
  }
});

test("the contents open only the section of the current page", async ({
  page,
}) => {
  const group = (section: string) =>
    page.locator(`.docs-nav details[data-section="${section}"]`);
  await page.goto("/examples/cantilever/");
  await expect(group("validation")).toHaveAttribute("open", "");
  await expect(group("examples")).not.toHaveAttribute("open");
  await expect(
    page.locator('.docs-nav a[aria-current="page"]'),
  ).toHaveAttribute("href", "/examples/cantilever/");
  await page.goto("/examples/mbb-beam-topopt/");
  await expect(group("examples")).toHaveAttribute("open", "");
  await expect(group("validation")).not.toHaveAttribute("open");
});

test("the pages are light by default and remember a switch to dark", async ({
  page,
}) => {
  const background = () =>
    page.evaluate(() => getComputedStyle(document.body).backgroundColor);
  await page.goto("/examples/cantilever/");
  expect(await background()).toBe("rgb(255, 255, 255)");
  const toggle = page.getByRole("button", {
    name: "Switch to the dark theme",
  });
  await toggle.click();
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
  // The choice holds on the next page, until switched back.
  await page.goto("/examples/");
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
  await page.getByRole("button", { name: "Switch to the light theme" }).click();
  expect(await background()).toBe("rgb(255, 255, 255)");
});

test("the retired /validation/ addresses redirect to the example pages", async ({
  page,
}) => {
  for (const [from, to] of [
    ["/validation/", "/examples/"],
    ["/validation/cantilever/", "/examples/cantilever/"],
    ["/validation/surface-traction/", "/examples/axial-bar/"],
    ["/examples/plate-with-hole", "/examples/plate-with-hole/"],
  ]) {
    const res = await page.request.get(from, { maxRedirects: 0 });
    expect(res.status(), from).toBe(301);
    expect(res.headers()["location"], from).toBe(to);
  }
});

// What each page says the app shows after a solve, and that the app shows it.
for (const id of IDS)
  test(`${id}: the app shows the read-out its page publishes`, async ({
    page,
  }) => {
    test.setTimeout(90_000);
    await page.goto(`/examples/${id}/`);
    const readout = page.getByTestId("app-readout");
    if ((await readout.count()) === 0) {
      // An optimization opens unsolved and publishes no solve read-out.
      await expect(page.getByTestId("reproduce-open")).toHaveAttribute(
        "href",
        `/app/?example=${id}`,
      );
      return;
    }
    const stat = await readout.getAttribute("data-stat");
    const field = await readout.getAttribute("data-field");
    const value = await readout.getAttribute("data-value");
    if (!stat || !field || !value)
      throw new Error(`${id}: the page's read-out is incomplete`);
    expect(value).toMatch(/^-?\d\.\d{3}e[+-]\d+ mm$/);

    await page.getByTestId("reproduce-open").click();
    await expect(page).toHaveURL(`/app/?example=${id}`);
    await page.waitForFunction(
      () =>
        (
          window as unknown as {
            __kofemStore?: { getState(): { nodes: unknown[] } };
          }
        ).__kofemStore?.getState().nodes.length,
      null,
      { timeout: 30_000 },
    );

    // Solve it in the browser (Studies → Static 1 → Run static solve), as the
    // page instructs; a stored result is replaced by the fresh one.
    await page.evaluate(() => {
      const win = window as unknown as {
        __kofemStore: { getState(): { result: unknown } };
        __storedResult: unknown;
      };
      win.__storedResult = win.__kofemStore.getState().result;
    });
    await page.getByTestId("tree-study-1").click();
    await page.getByRole("button", { name: /Run static solve/ }).click();
    await page.waitForFunction(
      () => {
        const win = window as unknown as {
          __kofemStore: { getState(): { result: unknown } };
          __storedResult: unknown;
        };
        const { result } = win.__kofemStore.getState();
        return result !== null && result !== win.__storedResult;
      },
      null,
      { timeout: 60_000 },
    );
    await page.getByTestId("tree-plot-1").click();
    await page.getByTestId("plot-field").selectOption(field);
    await expect(summaryValue(page, stat)).toHaveText(value);
  });
